INSERT INTO posts (slug,title,dek,body,category,author,status,published_at) VALUES ('about','About Rapaechelon','','<p>Rapaechelon, also known as RAPMAG and Rap Aechelon Mag, is an independent American music, entertainment and culture publication covering hip-hop, rap, breaking stories, entertainment, emerging artists and the communities shaping contemporary culture.</p><p>Rapaechelon was created to give readers direct access to stories across mainstream and independent entertainment while creating space for artists, creators and voices that may not always receive attention from larger media outlets.</p><p>Our coverage includes music releases, artist profiles and interviews, entertainment news, hip-hop culture, breaking news, commentary and selected local stories. We aim to publish clearly sourced, accessible reporting while distinguishing news reporting from commentary and promotional material.</p><p>Rap Aechelon Mag is registered as a U.S. publication in both online and print formats. The online edition carries ISSN 2832-2606 and the print edition carries ISSN 2832-2614.</p><p>Rapaechelon is committed to developing a publication readers can identify by its authors, sources, corrections, publication dates and editorial standards—not simply by the stories it publishes.</p>','page','Rapaechelon','published',datetime('now')) ON CONFLICT(slug) DO UPDATE SET body=excluded.body WHERE posts.slug='contact';
INSERT INTO posts (slug,title,dek,body,category,author,status,published_at) VALUES ('editorial-standards','Editorial Standards','','<p>Rapaechelon publishes reporting and editorial coverage across music, hip-hop, entertainment, culture, breaking news and selected local topics. Accuracy, attribution and transparency are central to our editorial process.</p><p>Writers and editors should verify material before publication and identify the source of factual claims whenever appropriate. Information obtained from another publication should be attributed and linked to the original or most authoritative available source whenever possible.</p><p>Headlines must accurately represent the article. We do not intentionally use headlines, images, metadata or descriptions that materially misrepresent the underlying story.</p><p>Direct quotations should not be altered in a way that changes their meaning. When information cannot be independently confirmed, the article should make that limitation clear rather than presenting the claim as established fact.</p><p>News reporting, opinion, sponsored material and promotional coverage should be distinguishable to readers. Commercial relationships should not be presented as independent editorial judgment.</p><p>Authors are responsible for the accuracy of their work, while Rapaechelon editors may review headlines, sourcing, formatting, images, links and other material before or after publication.</p><p>Articles may be updated as stories develop. Material changes should update the article''s modification date. Corrections should follow our Corrections Policy.</p>','page','Rapaechelon','published',datetime('now')) ON CONFLICT(slug) DO UPDATE SET body=excluded.body WHERE posts.slug='contact';
INSERT INTO posts (slug,title,dek,body,category,author,status,published_at) VALUES ('corrections-policy','Corrections Policy','','<p>Rapaechelon wants its published record to be accurate. When we determine that a published story contains a meaningful factual error, we will correct it as promptly as reasonably possible.</p><p>Minor spelling, grammar, formatting or typographical changes may be made without a correction notice when they do not alter the meaning of the article.</p><p>Material corrections—such as an incorrect name, date, quotation, attribution, location or factual claim—should be corrected in the article and, when appropriate, accompanied by a correction or update note explaining what changed.</p><p>Developing stories may be updated as additional verified information becomes available. An update is not necessarily a correction; the distinction depends on whether the original reporting was inaccurate.</p><p>We do not remove accurate published material solely because a person or organization later dislikes the coverage. Requests involving privacy, safety, legal concerns or substantial new evidence will be reviewed individually.</p><p>Readers who believe an article contains an error may contact Rapaechelon with the article URL, the disputed information and supporting information when available.</p>','page','Rapaechelon','published',datetime('now')) ON CONFLICT(slug) DO UPDATE SET body=excluded.body WHERE posts.slug='contact';
INSERT INTO posts (slug,title,dek,body,category,author,status,published_at) VALUES ('contact','Contact Rapaechelon','','<p>Have a news tip, correction, story idea, music submission or business inquiry? Contact the Rapaechelon team.</p><p>Editorial &amp; General Inquiries: <a href="mailto:rapaechelon@gmail.com">rapaechelon@gmail.com</a></p><p>When submitting a correction, include the article URL and a clear description of the information you believe should be reviewed.</p><p>Music and story submissions may be considered for coverage, but submission does not guarantee publication.</p><p>For sensitive news tips, avoid sending passwords, financial information or other unnecessary confidential personal information.</p>','page','Rapaechelon','published',datetime('now')) ON CONFLICT(slug) DO UPDATE SET body=excluded.body WHERE posts.slug='contact';
